#[test]
fn scratch_rewrite_of_first_line() {
    let dir = TempDir::new().unwrap();
    let path = session_path(dir.path(), "rw");
    let mut lines = m0_lines(3);
    lines[0] = session_start("rw", None);
    for line in &lines {
        append(&path, line);
    }
    let mut attach = Attach::start(&config(dir.path(), POLL_MS)).unwrap();
    let mut collected = Collected::default();
    pump(&mut attach, &mut collected, LIMIT, |a, _| a.at_eof());
    let mut grown = String::from_utf8(lines[0].clone()).unwrap();
    grown.insert_str(grown.len() - 2, ",\"title\":\"a generated title 123456789\"");
    let mut all = grown.into_bytes();
    for line in &lines[1..] {
        all.extend_from_slice(line);
    }
    let tail = lines[0].len();
    std::fs::write(&path, &all).unwrap();
    append(&path, b"");
    pump(&mut attach, &mut collected, LIMIT, |a, _| a.at_eof());
    collected.events.extend(attach.finish());
    for e in &collected.events {
        eprintln!("{:?} {:?} {}", e.kind.prd_name(), e.source, tail);
    }
    assert_eq!(unknown_events(&collected), 0);
}
